-- FazerCards provider (kind = custom) — يُضاف معطَّلاً وبلا مفتاح. الصق المفتاح من لوحة الأدمن ثم فعّله.
-- المسارات مأخوذة من وثائق SDK الرسمي (v0.2.0) وتحتاج تأكيداً بطلب تجريبي: راجع https://api.fzr.cards/public/docs
insert into public.smm_providers (id, name, kind, api_url, api_key, config, enabled)
values ('fazer', 'FazerCards', 'custom', 'https://api.fzr.cards/api/v2', '', '{"currency": "USD", "self_service": false, "balance": {"method": "GET", "path": "/balance", "headers": {"X-Api-Key": "{key}"}, "value": "balance", "currency": "currency"}, "order": {"method": "POST", "path": "/topups/order", "headers": {"X-Api-Key": "{key}", "Idempotency-Key": "{ref}"}, "body": {"category_id": "{country}", "offer_id": "{service}", "fields": {"player_id": "{input}"}}, "id": "id", "state": "status", "done": ["completed"], "failed": ["failed", "refund"], "error": "error"}, "status": {"method": "GET", "path": "/orders/{order}", "headers": {"X-Api-Key": "{key}"}, "state": "status", "done": ["completed"], "failed": ["failed", "refund"], "error": "error"}}'::jsonb, false)
on conflict (id) do update set name=excluded.name, kind=excluded.kind, api_url=excluded.api_url, config=excluded.config;
